-- These are sample brand concepts and sample PKR prices; confirm pricing, formulas and stock before taking live orders.
INSERT INTO categories(name,slug,sort_order,is_active) VALUES ('Signature fragrances','signature-fragrances',1,1) ON DUPLICATE KEY UPDATE name=VALUES(name),is_active=1;
INSERT INTO products(category_id,name,slug,sku,short_description,description,fragrance_family,concentration,gender,top_notes,heart_notes,base_notes,is_featured,is_active)
SELECT c.id,'Noor','noor','IKK-NOOR-01','A luminous floral-amber concept with a soft, golden finish.','Noor is imagined as first light across warm stone: bright, graceful and quietly memorable. A polished scent concept for everyday rituals and considered evenings.','Floral Amber','Eau de Parfum','Unisex','Bergamot, pear accord','Jasmine, orange blossom accord','Soft amber, musk accord',1,1 FROM categories c WHERE c.slug='signature-fragrances'
ON DUPLICATE KEY UPDATE name=VALUES(name),short_description=VALUES(short_description),description=VALUES(description),is_featured=1,is_active=1;
INSERT INTO products(category_id,name,slug,sku,short_description,description,fragrance_family,concentration,gender,top_notes,heart_notes,base_notes,is_featured,is_active)
SELECT c.id,'Sahra','sahra','IKK-SAHRA-01','Warm woods and amber-inspired character, made for golden-hour moods.','Sahra takes its cue from the last light of the day: a warm, enveloping fragrance concept with a confident woody character.','Woody Amber','Eau de Parfum','Unisex','Saffron accord, mandarin','Rose accord, cedar','Amber accord, sandalwood',1,1 FROM categories c WHERE c.slug='signature-fragrances'
ON DUPLICATE KEY UPDATE name=VALUES(name),short_description=VALUES(short_description),description=VALUES(description),is_featured=1,is_active=1;
INSERT INTO products(category_id,name,slug,sku,short_description,description,fragrance_family,concentration,gender,top_notes,heart_notes,base_notes,is_featured,is_active)
SELECT c.id,'Velvet Dusk','velvet-dusk','IKK-VELVET-01','A deep, smooth evening concept with a modern, velvety mood.','Velvet Dusk is a study in contrast: dark fruit-like brightness meets a soft, textured woody base. Designed as an expressive evening scent concept.','Ambery Woods','Eau de Parfum','Unisex','Blackcurrant accord, pink pepper','Iris accord, rose','Vanilla, patchouli accord',1,1 FROM categories c WHERE c.slug='signature-fragrances'
ON DUPLICATE KEY UPDATE name=VALUES(name),short_description=VALUES(short_description),description=VALUES(description),is_featured=1,is_active=1;
INSERT INTO products(category_id,name,slug,sku,short_description,description,fragrance_family,concentration,gender,top_notes,heart_notes,base_notes,is_featured,is_active)
SELECT c.id,'Azure 04','azure-04','IKK-AZURE-01','A fresh, airy aromatic concept with a clean, modern finish.','Azure 04 evokes open air after rain: crisp citrus, aromatic clarity and a calm woody foundation. A versatile daytime fragrance concept.','Fresh Aromatic','Eau de Parfum','Unisex','Bergamot, marine accord','Neroli, aromatic herbs','Cedar, clean musk accord',0,1 FROM categories c WHERE c.slug='signature-fragrances'
ON DUPLICATE KEY UPDATE name=VALUES(name),short_description=VALUES(short_description),description=VALUES(description),is_featured=0,is_active=1;
INSERT INTO product_variants(product_id,variant_name,volume_ml,sku,price,compare_at_price,stock_quantity,is_active)
SELECT p.id,'50 ml',50,CONCAT('IKK-',UPPER(REPLACE(p.slug,'-','')),'-50'),CASE p.slug WHEN 'noor' THEN 3490 WHEN 'sahra' THEN 3790 WHEN 'velvet-dusk' THEN 3990 ELSE 3290 END,NULL,20,1 FROM products p WHERE p.slug IN ('noor','sahra','velvet-dusk','azure-04')
ON DUPLICATE KEY UPDATE price=VALUES(price),stock_quantity=GREATEST(stock_quantity,20),is_active=1;
INSERT INTO product_images(product_id,image_path,alt_text,sort_order,is_primary)
SELECT p.id,CONCAT('/assets/images/',p.slug,'.svg'),CONCAT(p.name,' signature bottle artwork'),1,1 FROM products p WHERE p.slug IN ('noor','sahra','velvet-dusk','azure-04')
AND NOT EXISTS (SELECT 1 FROM product_images i WHERE i.product_id=p.id AND i.image_path=CONCAT('/assets/images/',p.slug,'.svg'));
